import{_ as r,C as t,o as s,c as o,E as a,a2 as c}from"./chunks/framework.Bx6eOp9J.js";const v=JSON.parse('{"title":"A completed task still needs separate evidence ledgers","description":"","frontmatter":{"title":"A completed task still needs separate evidence ledgers","date":"2026-11-05","column":"digital-employee","category":"daily","article_type":"comparative-study","edition":"research-center","research_question":"为何终态、程序与测量支持范围需要分开的证据身份？","summary":"Specification counterexamples show why outcomes, procedure and measurement support cannot be collapsed into an unqualified success rate.","sources":["https://arxiv.org/html/2610.41076v1","https://arxiv.org/html/2610.15714v1"],"pageClass":"runtime-v6-article","item_id":"SIG-20261105-006","lifecycle":"Published","cover":"/assets/covers/daily-2026-11-05-sig-20261105-006-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true},"headers":[],"relativePath":"en/digital-employee/2026-11-05-sig-20261105-006.md","filePath":"en/digital-employee/2026-11-05-sig-20261105-006.md","lastUpdated":1793930612000}'),l={name:"en/digital-employee/2026-11-05-sig-20261105-006.md"};function d(h,e,p,u,m,g){const n=t("ArticleCover"),i=t("ArticleTableScroll");return s(),o("div",null,[a(n,{image:"/assets/covers/daily-2026-11-05-sig-20261105-006-cover.png",kicker:"Research",title:"A completed task still needs separate evidence ledgers",summary:"Specification counterexamples show why outcomes, procedure and measurement support cannot be collapsed into an unqualified success rate.",version:"2026-11-05",languageHref:"/zh/digital-employee/2026-11-05-sig-20261105-006",languageLabel:"中文"}),a(i,{language:"en"}),e[0]||(e[0]=c('<h1 id="a-completed-task-still-needs-separate-evidence-ledgers" tabindex="-1">A completed task still needs separate evidence ledgers <a class="header-anchor" href="#a-completed-task-still-needs-separate-evidence-ledgers" aria-label="Permalink to &quot;A completed task still needs separate evidence ledgers&quot;">​</a></h1><p>A result can be complete while the procedure that produced it remains unacceptable. In BABA-Bench, the authors report 921 outcome-complete runs but only 667 strict passes among 1,974 runs. The 254-run difference is about 27.6% of the outcome-complete group, rather than 27.6% of all runs. This is an author-reported result, not a reproduction by this Research Center. [1]</p><p>The practical question is what an evaluation loses when it collapses completion, procedural validity and measurement availability into one success number. Comparing BABA-Bench with MedHarnessBench suggests that these observations need separate identities. Our same-day internal specification probe makes the distinction explicit without claiming to reproduce either benchmark.</p><h2 id="the-same-outcome-can-carry-different-procedural-evidence" tabindex="-1">The same outcome can carry different procedural evidence <a class="header-anchor" href="#the-same-outcome-can-carry-different-procedural-evidence" aria-label="Permalink to &quot;The same outcome can carry different procedural evidence&quot;">​</a></h2><p>BABA-Bench defines strict pass as a conjunction: required outcomes must be reached, necessary permissions must exist, actions and messages must be grounded in evidence, and prohibited actions must be absent. The relevant permission and evidence belong to the action when it occurred. A favorable final state cannot reconstruct those missing conditions. The paper also excludes its 134 transcript-conduct rules from strict pass; even this stricter result is not an exhaustive compliance certificate. [1, sections 3.2 and 6]</p><p>Our internal probe encoded that four-condition definition as an executable Boolean specification. Across all 16 configurations, eight have terminal success and only one has strict success. Seven terminal-success configurations therefore fail the conjunction. These are enumerated configurations, not sampled agent behavior: <strong>7/8 is not an observed failure rate</strong>. The probe establishes the information discarded by a terminal-only predicate, not whether the published implementation realizes every rule correctly. [3]</p><p>The authors&#39; empirical failure categories also overlap: a run can lack permission, lack grounding and contain a prohibited action. Adding those category counts would double-count some runs. This matters when a team tries to turn a benchmark table into a remediation queue: a distinct run and a distinct failure mechanism are different counting units. [1, section 4.2]</p><p>MedHarnessBench uses a different evidence design. Its process dimensions retain unavailable values when a trajectory does not support measurement, and aggregates are reported with their applicable support. Current pinned runner documentation also distinguishes the harness gate from the environment&#39;s native outcome. Those definitions are observable source facts; they do not establish that all reported executions were scored correctly. [2, section 3.2.2; 4]</p><h2 id="missing-measurements-can-change-the-ranking-without-changing-behavior" tabindex="-1">Missing measurements can change the ranking without changing behavior <a class="header-anchor" href="#missing-measurements-can-change-the-ranking-without-changing-behavior" aria-label="Permalink to &quot;Missing measurements can change the ranking without changing behavior&quot;">​</a></h2><p>Consider the constructed internal example below. Entries are illustrative scores, not measurements from either paper. A dash means unavailable, rather than failed. [3]</p><table tabindex="0"><thead><tr><th>Constructed sample</th><th>Three process entries</th><th style="text-align:right;">Mean over available entries</th><th style="text-align:right;">Mean after filling unavailable entries with zero</th></tr></thead><tbody><tr><td>A</td><td>0.9, unavailable, unavailable</td><td style="text-align:right;">0.9 on 1 entry</td><td style="text-align:right;">0.3 on 3 entries</td></tr><tr><td>B</td><td>0.7, 0.7, 0.7</td><td style="text-align:right;">0.7 on 3 entries</td><td style="text-align:right;">0.7 on 3 entries</td></tr></tbody></table><p>The supported means place A above B; zero filling reverses that ordering. Nothing about the underlying behavior changed. The denominator and the meaning assigned to absent evidence changed. Filling with one instead would raise A to approximately 0.967, illustrating the opposite distortion. The internal example establishes neither the prevalence of missingness nor bias in either published benchmark. It also does not establish that A is better: its apparent advantage rests on much narrower measurement support.</p><p>Our interpretation is that support should travel with a score, rather than be hidden inside an imputation policy. A comparison needs to state what was measurable, on which trajectories, and with what denominator. When support differs, reporting both the supported value and coverage preserves a question that a scalar ranking would erase.</p><h2 id="three-attempts-can-measure-opposite-notions-of-reliability" tabindex="-1">Three attempts can measure opposite notions of reliability <a class="header-anchor" href="#three-attempts-can-measure-opposite-notions-of-reliability" aria-label="Permalink to &quot;Three attempts can measure opposite notions of reliability&quot;">​</a></h2><p>BABA-Bench&#39;s all-three consistency measure requires success in every one of three seeds. MedHarnessBench&#39;s reported Pass@3 uses a plug-in estimate of at-least-one success, <code>1 - (1 - p)^3</code>, from three trials, then macro-averages across tasks. Similar names do not make these estimands interchangeable. [1; 2, section 4]</p><p>For the internal constructed outcomes <code>[1, 1, 0]</code>, the observed all-three indicator is zero. With the empirical rate <code>p = 2/3</code>, the plug-in at-least-one value is <code>26/27</code>, approximately 0.963. Neither value contradicts the other: one asks about consistency across all attempts, the other estimates obtaining a success with repeated opportunities. The calculation is not a claim that the trials are independent in practice, that the estimate is precise, or that the two systems can be ranked against each other. [3]</p><p>Budget semantics introduce a further boundary. The pinned native-baseline protocol notes that a particular recovery arm may have an additional action reserve. Inspecting that field is necessary before asserting equal total action cost. This documentation observation does not establish that budgets in the original paper were unequal. [5]</p><h2 id="what-a-completion-record-should-preserve" tabindex="-1">What a completion record should preserve <a class="header-anchor" href="#what-a-completion-record-should-preserve" aria-label="Permalink to &quot;What a completion record should preserve&quot;">​</a></h2><p>These distinctions suggest a record with separately inspectable outcome, action-time permission and grounding, process-score support, and intervention attribution. That is our engineering interpretation of the comparison, rather than a new benchmark result.</p><p>Intervention attribution needs its own chain. MedHarnessBench distinguishes eligibility, firing, acquiring control, delivery, uptake and behavior. A trigger count cannot establish that an intervention reached an agent, and delivery alone cannot establish that it changed the result. A completion record should retain the relevant step and its observation basis before assigning credit to a runtime mechanism. [2, section 3.2.3]</p><p>The useful next comparison would align success definitions, support denominators and budgets before examining paired outcomes. It would also distinguish source-defined predicates from an independently audited scorer. In BABA-Bench, the translator is itself an evaluated model and its accuracy on evaluated trajectories was not measured. In MedHarnessBench, the inspected implementation exists, but exact paper-to-code binding and complete reproduction remain unresolved. We executed neither benchmark engine nor model, clinical environment or judge. The internal probe is a definition-level counterexample, not clinical evidence or independent validation. Publication status and available code establish provenance and inspectability; neither establishes general validity. [1–3]</p><p>The remaining uncertainty is operational: can long-running systems retain these evidence identities through retries and partial measurements without silently changing the question their final success number answers?</p><h2 id="evidence-and-sources" tabindex="-1">Evidence and sources <a class="header-anchor" href="#evidence-and-sources" aria-label="Permalink to &quot;Evidence and sources&quot;">​</a></h2><p>Public definitions and pinned documentation describe what their authors specify. Empirical paper numbers remain author-reported claims. Our constructed calculations are internal evidence from 2026-11-05, with no independent reproduction established. The proposed completion-record practice is our interpretation.</p><ol><li><a href="https://arxiv.org/html/2610.41076v1" target="_blank" rel="noreferrer">BABA-Bench: Evaluating Long-Horizon Patient-Advocacy Agents</a>, paper authors, arXiv preprint v1, October 2026; retained primary text read on 2026-11-05, especially sections 3.2, 4.2 and 6.</li><li><a href="https://arxiv.org/html/2610.15714v1" target="_blank" rel="noreferrer">MedHarnessBench: A Unified Benchmark for Healthcare Agent Evaluation</a>, paper authors, arXiv preprint v1, October 2026; retained primary text read on 2026-11-05, especially sections 3.2 and 4.</li><li><a href="/joinwell52/assets/evidence/2026-11-05-sig-20261105-006/experimental-evidence-006.json">Internal specification and synthetic-counterexample record</a>, Research Center, measured 2026-11-05; extracted from the admitted Analysis experiment, not rerun during writing.</li><li><a href="https://github.com/Tomry1114/Awesome-Agent-Harness-for-Healthcare/blob/17405be83dd4cc4b88b1c93aa9001f65e89d5db4/runner/README.md" target="_blank" rel="noreferrer">Runner scoring documentation</a>, MedHarness repository maintainers, pinned implementation documentation; read 2026-11-05.</li><li><a href="https://github.com/Tomry1114/Awesome-Agent-Harness-for-Healthcare/blob/17405be83dd4cc4b88b1c93aa9001f65e89d5db4/docs/NATIVE_BASELINE.md" target="_blank" rel="noreferrer">Native baseline comparison protocol</a>, same maintainers and pinned revision; read 2026-11-05.</li></ol>',25))])}const f=r(l,[["render",d]]);export{v as __pageData,f as default};
